Require Import skylabs.prelude.base.

#[local] Open Scope Z_scope.

(** Public state model for [std::optional<int>]. *)
Definition optional_state : Type := option Z.

(** Whether an optional state contains a value. *)
Definition is_engaged (state : optional_state) : bool :=
  match state with
  | None => false
  | Some _ => true
  end.

Succeed Example is_engaged_none : is_engaged None = false := eq_refl.
Succeed Example is_engaged_zero : is_engaged (Some 0) = true := eq_refl.
Succeed Example is_engaged_value : is_engaged (Some 5) = true := eq_refl.

