(* [specify]'s string/notation form (as in [tests/specify/templates.v]) is the
   only registration idiom that can express a constructor/member *template*
   instantiation, whose emitted name is a doubly-nested
   [Ninst (Nscoped (Ninst optional [..]) (Nctor/Nfunction/Nop ..)) [..]].
   The [specify.template.*] combinators only build a single-[Ninst] name (a
   member of a class-template instantiation), so they cannot register these. *)
Import specify_notation.

Section with_cpp.
  Context `{Σ : cpp_logic, σ : genv}.

  Definition default_ctor_spec :=
    specify.template.ctor optionalN [] $
      \this this
      \post this |-> optionalR 1$m None.
